select pg_try_advisory_xact_lock(
        ('x' || substr(md5($1), 1, 16))::bit(64)::bigint
      ) as locked, 'outbox_merge' as lock_scope

select * from "computed_update_outbox" where "base_id" = $1 and "worker_lane" = $2 and "seed_table_id" = $3 and (("plan_hash" = $4 or regexp_replace(plan_hash, $5, '') = $6) and (not (coalesce(dirty_stats, '{}'::jsonb) ?| array[
      'ledgerScopeId', 'seedAllCursors', 'partialStageBudget', 'fieldBackfillCursor'
    ]) and not exists (select 1 as "one" from "computed_update_stage_ledger" where "scope_id" = "computed_update_outbox"."id") and not exists (select 1 as "one" from "computed_update_change_frontier" where "scope_id" = "computed_update_outbox"."id"))) and "change_type" = $7 and "status" = $8 order by "created_at", "id" limit $9 for update

select pg_try_advisory_xact_lock(
        ('x' || substr(md5($1), 1, 16))::bit(64)::bigint
      ) as locked, true as lock_scope_outbox_claim_base

select * from "computed_update_outbox" where "base_id" = $1 and "worker_lane" = $2 and "seed_table_id" = $3 and "change_type" = $4 and (("plan_hash" = $5 or regexp_replace(plan_hash, $6, '') = $7) and (not (coalesce(dirty_stats, '{}'::jsonb) ?| array[
      'ledgerScopeId', 'seedAllCursors', 'partialStageBudget', 'fieldBackfillCursor'
    ]) and not exists (select 1 as "one" from "computed_update_stage_ledger" where "scope_id" = "computed_update_outbox"."id") and not exists (select 1 as "one" from "computed_update_change_frontier" where "scope_id" = "computed_update_outbox"."id"))) and "status" = $8 and "next_run_at" <= $9 and "id" not in ($10) order by "created_at", "id" limit $11 for update skip locked

