select k.key as key, pg_try_advisory_xact_lock(k.lock_key) as locked
  from (
    select t.key as key, ('x' || substr(md5(t.key), 1, 16))::bit(64)::bigint as lock_key
    from unnest($1::text[]) with ordinality as t(key, ord)
    order by t.ord
  ) k

